1325  // The demangler entry point.
  1326  bool Demangle(const char *mangled, char *out, size_t out_size) {
  1327  #if defined(GLOG_OS_WINDOWS)
  1328  #if defined(HAVE_DBGHELP)
  1329    // When built with incremental linking, the Windows debugger
  1330    // library provides a more complicated `Symbol->Name` with the
  1331    // Incremental Linking Table offset, which looks like
  1332    // `@ILT+1105(?func@Foo@@SAXH@Z)`. However, the demangler expects
  1333    // only the mangled symbol, `?func@Foo@@SAXH@Z`. Fortunately, the
  1334    // mangled symbol is guaranteed not to have parentheses,
  1335    // so we search for `(` and extract up to `)`.
  1336    //
  1337    // Since we may be in a signal handler here, we cannot use `std::string`.
  1338    char buffer[1024];  // Big enough for a sane symbol.
  1339    const char *lparen = strchr(mangled, '(');
  1340    if (lparen) {
  1341      // Extract the string `(?...)`
  1342      const char *rparen = strchr(lparen, ')');
  1343      size_t length = static_cast<size_t>(rparen - lparen) - 1;
  1344      strncpy(buffer, lparen + 1, length);
  1345      buffer[length] = '\0';
  1346      mangled = buffer;
  1347    } // Else the symbol wasn't inside a set of parentheses
  1348    // We use the ANSI version to ensure the string type is always `char *`.
  1349    return UnDecorateSymbolName(mangled, out, out_size, UNDNAME_COMPLETE);
  1350  #else
  1351    (void)mangled;
  1352    (void)out;
  1353    (void)out_size;
  1354    return false;
  1355  #endif
  1356  #else
  1357    State state;
  1358    InitState(&state, mangled, out, out_size);
  1359    return ParseTopLevelMangledName(&state) && !state.overflowed;
  1360  #endif
  1361  }
